import {registry,spells,newBuild,steps,stats,raceFor,raceTraits,replacementFor,effectiveScores,choiceEvents,eligibleOptions,calculated,spellCounts,buildIssues,previewBuild} from '../features/characters/rules/build.mjs';
import {sessionUser} from './session.mjs';
import {recordId} from './record-id.mjs';
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const opt=(id,label,current,disabled=false)=>`<option value="${e(id)}" ${id===current?'selected':''} ${disabled?'disabled':''}>${e(label)}</option>`;
const panel=(title,html)=>`<section class="rw-panel"><h2>${e(title)}</h2>${html}</section>`;
const field=(label,html)=>`<label class="rw-field"><span>${e(label)}</span>${html}</label>`;
const input=(value,attributes)=>`<input ${attributes} value="${e(value)}">`;
const check=(label,attributes,checked,help='')=>`<label class="rw-check"><input type="checkbox" ${attributes} ${checked?'checked':''}><span>${e(label)}${help?'<small>'+e(help)+'</small>':''}</span></label>`;
export function renderBuild(b,step,{query='',level='all',message='',legacy=false}={}){
 const race=raceFor(b),racial=raceTraits(b),scores=effectiveScores(b);let body='';
 if(step===0)body=`<p class="rw-source">FFD20</p>${field('Character name',input(b.name,'data-rw-field="name" maxlength="80" autocomplete="off"'))}${field('Alignment',input(b.alignment,'data-rw-field="alignment" maxlength="80"'))}${field('Biography',`<textarea data-rw-field="bio" maxlength="2000" rows="4">${e(b.bio)}</textarea>`)}${field('Portrait',`<input type="file" data-rw-portrait accept="image/png,image/jpeg,image/webp">`)}${b.portrait?'<img class="rw-portrait" src="'+e(b.portrait)+'" alt="Character portrait">':''}`;
 if(step===1)body=`<p>Enter scores <strong>before racial adjustments</strong>.</p>${legacy?'<p class="rw-notice">Existing sheet totals may already include racial bonuses. Enter the original base scores here before applying this build. A copy of the original sheet will be retained.</p>':''}<div class="rw-score-grid">${stats.map(k=>field(k.toUpperCase(),input(b.baseScores[k],`type="number" data-rw-score="${k}" min="1" max="45" step="1"`)+`<small>Total ${scores[k]} · modifier ${Math.floor((scores[k]-10)/2)>=0?'+':''}${Math.floor((scores[k]-10)/2)}</small>`)).join('')}</div>`;
 if(step===2){body=field('Race',`<select data-rw-field="raceId">${opt('','Choose a race',b.raceId)}${registry.races.map(r=>opt(r.id,r.name,b.raceId)).join('')}</select>`);
  if(race){body+=field('Heritage',`<select data-rw-field="heritageId">${opt('','Standard heritage',b.heritageId)}${race.data.heritages.map(h=>opt(h.id,h.name,b.heritageId)).join('')}</select>`);const h=race.data.heritages.find(h=>h.id===b.heritageId);if(h)body+='<p class="field-help">'+e(h.description)+'</p>';
   body+=panel('Standard racial traits',race.data.standardTraitIds.map(id=>{const f=race.features.find(f=>f.id===id),replaced=racial.replaced.includes(id);return `<div class="rw-trait">${check(f.name,`data-rw-trait="${id}" ${replaced?'disabled':''}`,!b.disabledTraits.includes(id),replaced?'Replaced by your selection':'Enabled by default')}<details><summary>Details</summary><p>${e(f.description)}</p></details></div>`;}).join(''));
   body+=panel('Alternate racial traits',race.data.alternateTraitIds.map(id=>{const f=race.features.find(f=>f.id===id),ops=replacementFor(race,id),available=ops.length&&ops.every(o=>o.resolution==='resolved'&&o.operation==='replace'&&o.scope==='whole_feature');return `<div class="rw-trait">${check(f.name,`data-rw-alternate="${id}" ${available?'':'disabled'}`,b.alternateIds.includes(id),available?ops.map(o=>o.description).join(' '):'Replacement mapping pending')}<details><summary>Details</summary><p>${e(f.description)}</p></details></div>`;}).join(''));
  }
 }
 if(step===3)body=field('Class',`<select><option>Black Mage</option></select>`)+field('Class level',input(b.level,'type="number" data-rw-level min="1" max="20" step="1"'))+field('Archetype',`<select data-rw-field="archetypeId">${opt('','Base Black Mage',b.archetypeId)}${registry.archetypes.map(a=>opt(a.id,a.name+' · checking rules',b.archetypeId,true)).join('')}</select>`)+`<p class="field-help">Archetypes appear as their replacement and casting rules become available.</p>`+panel('Class progression',`<p>Hit Die d6 · skill ranks 4 + INT modifier per level.</p><p>Class skills: Appraise, Craft, Fly, all Knowledge skills, Linguistics, Profession and Spellcraft.</p>`);
 if(step===4){body=panel('Hit points by level',`<p class="field-help">Enter each d6 result before CON. CON is added once per level, with a minimum of 1 HP per level.</p><div class="rw-hp-grid">${Array.from({length:b.level},(_,i)=>field('Level '+(i+1),input(b.hpRolls[i]??'',`type="number" min="1" max="6" step="1" data-rw-hp="${i}"`))).join('')}</div>`);
  body+=panel('Favored class rewards',`<p class="field-help">Choose a reward only for levels taken in a favored class.</p>${Array.from({length:b.level},(_,i)=>field('Level '+(i+1),`<select data-rw-favored="${i}">${opt('','No favored reward',b.favored[i]||'')}${opt('hp','+1 HP',b.favored[i])}${opt('skill','+1 skill rank',b.favored[i])}${opt('racial','Race-specific reward',b.favored[i])}</select>`)).join('')}<details><summary>Race-specific reward</summary><p>${e(race?.data.favoredRewards[0]?.description||'Select a race first.')}</p><p class="field-help">Conditional crafting/damage rewards are recorded as rules text, not unconditional bonuses.</p></details>`);
  body+=choiceEvents(b).map(event=>{const count=calculated(event.count,b),pool=registry.class.choicePools.find(p=>event.poolIds.includes(p.id));return panel(`${pool.name} · level ${event.atClassLevel}`,Array.from({length:Math.min(10,count)},(_,i)=>{const selected=b.choices[event.id]?.[i]||'',o=pool.options.find(o=>o.id===selected);return field('Choice '+(i+1),`<select data-rw-choice="${event.id}" data-choice-index="${i}">${opt('','Choose an option',selected)}${eligibleOptions(b,event).map(o=>opt(o.id,o.name,selected)).join('')}</select>`)+(o?`<p class="rw-option-desc">${e(o.description)}</p>`:'');}).join(''));}).join('');
 }
 if(step===5){const counts=spellCounts(b),max=Math.min(9,Math.ceil(b.level/2),scores.int-10),selected=b.spellIds.map(id=>spells.find(s=>s.id===id)).filter(Boolean),available=spells.filter(s=>s.level<=Math.max(0,max)&&(level==='all'||s.level===Number(level))&&(!query||(s.name+' '+s.summary).toLowerCase().includes(query.toLowerCase())));
  body=`<p class="rw-notice">Spell descriptions were restored from your backup. Use the source link to check an individual spell. Learning spells does not spend MP.</p><p><strong>${selected.filter(s=>s.level===0).length} / ${counts.cantrips}</strong> cantrips · <strong>${selected.filter(s=>s.level>0).length} / ${counts.leveled}</strong> other spells</p>${field('Find a spell',input(query,'type="search" data-rw-search placeholder="Spell name or description"'))}<div class="rw-levels">${Array.from({length:Math.max(0,max)+1},(_,n)=>`<button type="button" class="button ${level===String(n)?'primary':''}" data-rw-spell-level="${n}">${n}</button>`).join('')}<button type="button" class="button ${level==='all'?'primary':''}" data-rw-spell-level="all">All</button><button class="button" type="button" data-rw-selected>Selected</button></div><p class="field-help">First- and second-class-level choices must be 1st-level spells. Later choices must have been available at the level gained.</p><div class="rw-spells">${available.slice(0,45).map(s=>`<article class="rw-panel ${b.spellIds.includes(s.id)?'rw-chosen':''}"><h2>${e(s.name)}</h2><small>Level ${s.level} · ${s.level} MP</small><p>${e(s.summary)}</p><details><summary>Description</summary><p>${e(s.description)}</p><p>${e([s.castingTime,s.range,s.duration,s.save].filter(Boolean).join(' · '))}</p><a href="${e(s.url)}" target="_blank" rel="noopener">Official spell page ↗</a></details><button type="button" class="button ${b.spellIds.includes(s.id)?'primary':''}" data-rw-spell="${s.id}">${b.spellIds.includes(s.id)?'✓ Learned':'Learn spell'}</button></article>`).join('')}</div>${available.length>45?'<p>Showing the first 45 matches. Filter by name or spell level.</p>':''}`;
 }
 if(step===6){const p=previewBuild(b),problems=buildIssues({...b,reviewed:true});body=`<div class="rw-preview"><h2>${e(b.name)}</h2><p>${e(race?.name)} · Black Mage ${b.level}</p><div class="rw-totals">${[['HP',p.hp],['Base MP',p.summary.baseMp],['Bonus MP',p.summary.bonusMp],['Total MP',p.summary.mp],['BAB','+'+p.summary.bab],['Fortitude',p.summary.fort+Math.floor((scores.con-10)/2)],['Reflex',p.summary.ref+Math.floor((scores.dex-10)/2)],['Will',p.summary.will+Math.floor((scores.wis-10)/2)],['Skill rank budget',p.skillBudget]].map(([label,value])=>`<div><span>${label}</span><strong>${value}</strong></div>`).join('')}</div></div>${panel('Effective ability scores','<div class="rw-score-grid">'+stats.map(k=>`<div><span>${k.toUpperCase()}</span><strong>${scores[k]}</strong><small>${b.baseScores[k]} base ${scores[k]-b.baseScores[k]>=0?'+':''}${scores[k]-b.baseScores[k]} race</small></div>`).join('')+'</div>')}${panel('Class features','<ul>'+p.features.map(f=>'<li>'+e(f.name)+'</li>').join('')+'</ul>')}${problems.length?'<div class="rw-notice rw-error"><strong>Still needed</strong><ul>'+problems.map(p=>'<li>'+e(p.message)+'</li>').join('')+'</ul></div>':''}<p class="field-help">Conditional bonuses and special rules remain on their ability cards. They are not added to every roll. Spells and uses should be checked before play.</p>${check('I reviewed the scores, choices and conditional rules.','data-rw-reviewed',b.reviewed)}`;}
 return `<section class="rw-wizard"><div class="rw-progress" aria-label="Character creation progress">${steps.map((_,i)=>'<span class="'+(i<=step?'rw-done':'')+'"></span>').join('')}</div><h1>${steps[step]} <small>${step+1} / ${steps.length}</small></h1>${message?'<p class="rw-notice rw-error" role="alert">'+e(message)+'</p>':''}${body}<p class="rw-status" data-rw-status role="status"></p><div class="wizard-actions"><button type="button" class="button" data-rw-back>${step?'← Back':'Characters'}</button><button type="button" class="button primary" data-rw-next>${step===6?'Save & open sheet':'Next →'}</button></div></section>`;
}
export function mountRulesWizard(){
 const main=document.querySelector('main'),control=new AbortController(),id=new URL(location.href).searchParams.get('characterId'),live=document.body.dataset.mode==='live';let closed=false,b=newBuild(),step=0,character=null,query='',spellLevel='all',message='',key='',draftId=recordId(),saving=false;
 function saveDraft(){if(!key)return;try{sessionStorage.setItem(key,JSON.stringify({b,step,draftId}));}catch{}}
 function draw(focus=false){if(closed)return;main.innerHTML=renderBuild(b,step,{query,level:spellLevel,message,legacy:Boolean(character&&!character.data.rulesBuild)});if(focus){main.querySelector('h1').setAttribute('tabindex','-1');main.querySelector('h1').focus();window.scrollTo(0,0);}}
 const changed=()=>{b.reviewed=false;message='';saveDraft();};
 function error(e){message=e.message||'Could not save this build.';draw();}
 async function init(){main.innerHTML='<p role="status">Loading character builder…</p>';try{
  const response=await fetch('/api/v1/auth/session',{credentials:'same-origin',signal:control.signal,cache:'no-store'});if(!response.ok)throw Error('Sign in to create or edit a character.');const user=(await response.json()).user;if(!user)throw Error('Sign in to create a character.');
  key='comos-rules-draft:'+user.id+':'+(id||'new');
  if(id){const r=await fetch('/api/v1/character-records/'+encodeURIComponent(id),{credentials:'same-origin',signal:control.signal,cache:'no-store'});const j=await r.json();if(!r.ok)throw Error(j.message||'Character unavailable.');character=j.character;if(character.data.rulesBuild?.input)b=structuredClone(character.data.rulesBuild.input);else{b.name=character.name;b.alignment=character.data.alignment||'';b.bio=character.data.bio||'';b.portrait=character.data.portrait||'';}}
  try{const cached=JSON.parse(sessionStorage.getItem(key)||'null');if(cached?.b?.version===registry.version&&Number.isInteger(cached.step)&&cached.step>=0&&cached.step<7&&typeof cached.draftId==='string'){b=cached.b;step=cached.step;draftId=cached.draftId;}}catch{}
  draw();
 }catch(error){if(!closed)main.innerHTML='<p role="alert">'+e(error.message)+'</p><a class="button" href="signin.html">Sign in</a>';}}
 async function finish(){if(saving)return;const found=buildIssues(b);if(found.length){message=found[0].message;step=found[0].step;draw(true);return;}if(!live){message='This preview does not save real characters.';draw();return;}saving=true;main.querySelector('[data-rw-next]').disabled=true;main.querySelector('[data-rw-status]').textContent='Saving…';
  try{const url=id?'/api/v1/character-records/'+encodeURIComponent(id):'/api/v1/my/characters';const body=id?{op:'wizard-build',revision:character.revision,build:b}:{build:b,requestId:draftId};const response=await fetch(url,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:control.signal});const payload=await response.json();if(!response.ok)throw Error(payload.message||'Could not save. Your draft is kept.');sessionStorage.removeItem(key);if(!closed)location.assign('sheet.html?characterId='+encodeURIComponent(payload.character.id));}
  catch(e){if(!closed){saving=false;error(e);}}
 }
 main.addEventListener('input',event=>{const t=event.target;if(t.matches('[data-rw-field]'))b[t.dataset.rwField]=t.value;if(t.matches('[data-rw-score]'))b.baseScores[t.dataset.rwScore]=Number(t.value);if(t.matches('[data-rw-level]'))b.level=Number(t.value);if(t.matches('[data-rw-hp]'))b.hpRolls[Number(t.dataset.rwHp)]=Number(t.value);if(t.matches('[data-rw-search]')){query=t.value;draw();const search=main.querySelector('[data-rw-search]');search.focus();search.setSelectionRange(query.length,query.length);return;}changed();},{signal:control.signal});
 main.addEventListener('change',async event=>{const t=event.target;try{
  if(t.matches('[data-rw-field]')){const k=t.dataset.rwField;b[k]=t.value;if(k==='raceId'){b.heritageId='';b.disabledTraits=[];b.alternateIds=[];}changed();draw();}
  if(t.matches('[data-rw-score],[data-rw-level]')){changed();draw();}
  if(t.matches('[data-rw-trait]')){const id=t.dataset.rwTrait;b.disabledTraits=t.checked?b.disabledTraits.filter(v=>v!==id):[...new Set([...b.disabledTraits,id])];changed();draw();}
  if(t.matches('[data-rw-alternate]')){const id=t.dataset.rwAlternate,old=[...b.alternateIds];b.alternateIds=t.checked?[...new Set([...b.alternateIds,id])]:b.alternateIds.filter(v=>v!==id);const errors=raceTraits(b).errors;if(errors.length){b.alternateIds=old;message=errors[0];draw();return;}changed();draw();}
  if(t.matches('[data-rw-favored]')){const index=Number(t.dataset.rwFavored);b.favored=Array.from({length:b.level},(_,i)=>i===index?t.value:b.favored[i]||'');changed();draw();}
  if(t.matches('[data-rw-choice]')){b.choices[t.dataset.rwChoice]??=[];b.choices[t.dataset.rwChoice][Number(t.dataset.choiceIndex)]=t.value;changed();draw();}
  if(t.matches('[data-rw-reviewed]')){b.reviewed=t.checked;saveDraft();}
  if(t.matches('[data-rw-portrait]')){const file=t.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>3000000)throw Error('Choose JPG, PNG or WebP under 3 MB.');const bitmap=await createImageBitmap(file);try{const canvas=document.createElement('canvas'),ratio=Math.min(1,350/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const portrait=canvas.toDataURL('image/jpeg',.75);if(portrait.length>150000)throw Error('Try a smaller portrait.');b.portrait=portrait;}finally{bitmap.close();}changed();draw();}
 }catch(e){error(e);}},{signal:control.signal});
 main.addEventListener('click',event=>{const t=event.target.closest('button');if(!t||saving)return;
  if(t.matches('[data-rw-back]')){if(step){step--;saveDraft();message='';draw(true);}else location.assign('characters.html');}
  if(t.matches('[data-rw-next]')){if(step===6){void finish();return;}const invalid=buildIssues(b).filter(i=>i.step<=step&&i.step!==6);if(invalid.length){message=invalid[0].message;draw();return;}step++;message='';saveDraft();draw(true);}
  if(t.matches('[data-rw-spell-level]')){spellLevel=t.dataset.rwSpellLevel;draw();}
  if(t.matches('[data-rw-spell]')){const id=t.dataset.rwSpell;b.spellIds=b.spellIds.includes(id)?b.spellIds.filter(v=>v!==id):[...b.spellIds,id];changed();draw();}
  if(t.matches('[data-rw-selected]')){message=b.spellIds.map(id=>spells.find(s=>s.id===id)?.name).join(', ')||'No spells selected.';draw();}
 },{signal:control.signal});
 void init();return ()=>{closed=true;control.abort();};
}
